class Solution {
    private fun factorSum(valueInput:Int):Int{
        var value=valueInput;
        var sum=0;
        var divisor=2;
        while(divisor*divisor<=value){
            while(value%divisor==0){
                sum+=divisor;
                value/=divisor
            };
            divisor++
        };
        if(value>1)sum+=value;
        return sum
    }
